PRAGMA foreign_keys=ON;
CREATE TABLE physical_row(ordinal INTEGER PRIMARY KEY CHECK(ordinal>=0), evidence_ref TEXT NOT NULL UNIQUE, source_path TEXT NOT NULL, pointer TEXT NOT NULL UNIQUE, native_key TEXT NOT NULL, raw_json TEXT NOT NULL CHECK(json_valid(raw_json)), raw_sha256 TEXT NOT NULL) STRICT;
CREATE TABLE text_owner(row_ordinal INTEGER NOT NULL REFERENCES physical_row(ordinal), field TEXT NOT NULL, hash TEXT NOT NULL, semantic_role TEXT NOT NULL, PRIMARY KEY(row_ordinal,field)) WITHOUT ROWID, STRICT;
CREATE TABLE text_resolution(row_ordinal INTEGER NOT NULL, field TEXT NOT NULL, locale TEXT NOT NULL CHECK(locale IN ('CHS','EN','JP')), state TEXT NOT NULL CHECK(state IN ('resolved_unique','resolved_candidate_set','missing')), candidate_count INTEGER NOT NULL CHECK(candidate_count>=0), PRIMARY KEY(row_ordinal,field,locale), FOREIGN KEY(row_ordinal,field) REFERENCES text_owner(row_ordinal,field)) WITHOUT ROWID, STRICT;
CREATE TABLE text_candidate(row_ordinal INTEGER NOT NULL, field TEXT NOT NULL, locale TEXT NOT NULL, tier TEXT NOT NULL CHECK(tier IN ('main','medium')), source_path TEXT NOT NULL, pair_ordinal INTEGER NOT NULL CHECK(pair_ordinal>=0), hash TEXT NOT NULL, raw_text TEXT NOT NULL, PRIMARY KEY(row_ordinal,field,locale,tier,pair_ordinal), FOREIGN KEY(row_ordinal,field,locale) REFERENCES text_resolution(row_ordinal,field,locale)) WITHOUT ROWID, STRICT;
CREATE TABLE locator(row_ordinal INTEGER NOT NULL REFERENCES physical_row(ordinal), field TEXT NOT NULL, item_ordinal INTEGER NOT NULL CHECK(item_ordinal>=-1), raw_value TEXT NOT NULL CHECK(json_valid(raw_value)), target_family TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('resolved_unique','resolved_candidate_set','missing','mapping_unresolved','absent_discriminator','not_applicable','terminal_omitted','terminal_zero','terminal_empty')), candidate_count INTEGER NOT NULL CHECK(candidate_count>=0), PRIMARY KEY(row_ordinal,field,item_ordinal)) WITHOUT ROWID, STRICT;
CREATE TABLE physical_candidate(row_ordinal INTEGER NOT NULL, field TEXT NOT NULL, item_ordinal INTEGER NOT NULL, target_ordinal INTEGER NOT NULL CHECK(target_ordinal>=0), target_source_path TEXT NOT NULL, target_pointer TEXT NOT NULL, PRIMARY KEY(row_ordinal,field,item_ordinal,target_ordinal), FOREIGN KEY(row_ordinal,field,item_ordinal) REFERENCES locator(row_ordinal,field,item_ordinal)) WITHOUT ROWID, STRICT;
CREATE TABLE release(id INTEGER PRIMARY KEY CHECK(id=1), payload TEXT NOT NULL CHECK(json_valid(payload))) STRICT;
CREATE INDEX physical_native_key ON physical_row(native_key,ordinal);
CREATE INDEX text_literal_scope ON text_candidate(locale,row_ordinal,field);
CREATE INDEX physical_reverse_candidate ON physical_candidate(target_source_path,target_ordinal,row_ordinal);
